def find_Product(arr, n):
    if n == 1:
        return arr[0]

    # Initialize variables for product and occurrence count
    product = 1
    occurances = {}

    # Count occurrences of each element
    for num in arr:
        if num in occurances:
            occurances[num] += 1
        else:
            occurances[num] = 1

    # Calculate the product of non-repeated elements
    for key in occurances:
        if occurances[key] == 1:
            product *= key

    return product

